// Le body reçu est un tableau de posts, chacun avec un tableau commentsData imbriqué
// (format exporté par le bouton "Envoyer vers n8n" de l'extension).
// On aplatit tout en items individuels, marqués par recordType ('post' ou 'comment'),
// pour pouvoir les router ensuite vers la bonne table PostgreSQL via un noeud IF.
const posts = $input.first().json.body;
const output = [];

for (const p of posts) {
  output.push({
    json: {
      recordType: 'post',
      postId: p.postId,
      feedbackId: p.feedbackId || null,
      actors: p.actors,
      text: p.text,
      html: p.html,
      attachments: p.attachments,
      subattachments: p.subattachments,
      comments: p.comments || 0,
      likes: p.likes || 0,
      shares: p.shares || 0,
      pageUrl: p.pageUrl,
      postUrl: p.postUrl,
      publishTime: p.publishTime || null,
      scrapedAt: p.scrapedAt,
    }
  });
  for (const c of (p.commentsData || [])) {
    output.push({
      json: {
        recordType: 'comment',
        commentId: c.commentId,
        postId: p.postId,
        isReply: c.isReply ? true : false,
        parentCommentId: c.parentCommentId || null,
        actors: c.actors,
        text: c.text,
        html: c.html,
        attachments: c.attachments,
        likes: c.likes || 0,
        commentUrl: c.commentUrl,
        scrapedAt: c.scrapedAt,
      }
    });
  }
}

return output;
